import { useMemo, useState, type KeyboardEvent } from 'react';
import {
  JxBadge,
  JxButton,
  JxChip,
  JxDivider,
  JxEmptyState,
  JxPagination,
  JxProgressCircle,
} from '@jinx-ui/react';

type SpendStatus = 'ok' | 'warning' | 'over' | 'paused';

type Project = {
  id: string;
  name: string;
  quotaUsed: number;
  status: SpendStatus;
};

const STATUS_META: Record<
  SpendStatus,
  { label: string; tone: 'success' | 'warning' | 'danger' | 'default' }
> = {
  ok: { label: 'В норме', tone: 'success' },
  warning: { label: 'Близко к лимиту', tone: 'warning' },
  over: { label: 'Превышение', tone: 'danger' },
  paused: { label: 'Приостановлен', tone: 'default' },
};

const STATUS_ORDER: SpendStatus[] = ['ok', 'warning', 'over', 'paused'];

const PROJECTS: Project[] = [
  { id: 'p-1', name: 'Витрина маркетплейса', quotaUsed: 34, status: 'ok' },
  { id: 'p-2', name: 'Платёжный шлюз', quotaUsed: 81, status: 'warning' },
  { id: 'p-3', name: 'Аналитика и отчёты по когортам пользователей', quotaUsed: 118, status: 'over' },
  { id: 'p-4', name: 'Мобильный клиент iOS', quotaUsed: 47, status: 'ok' },
  { id: 'p-5', name: 'Сервис уведомлений', quotaUsed: 92, status: 'warning' },
  { id: 'p-6', name: 'ETL-конвейер', quotaUsed: 12, status: 'paused' },
  { id: 'p-7', name: 'Поиск по каталогу', quotaUsed: 66, status: 'ok' },
  { id: 'p-8', name: 'Биллинг', quotaUsed: 104, status: 'over' },
  { id: 'p-9', name: 'Админ-панель', quotaUsed: 28, status: 'paused' },
  { id: 'p-10', name: 'Рекомендации', quotaUsed: 73, status: 'warning' },
  { id: 'p-11', name: 'Медиа-хранилище', quotaUsed: 55, status: 'ok' },
  { id: 'p-12', name: 'Антифрод', quotaUsed: 97, status: 'warning' },
];

const PAGE_SIZE = 5;

export default function ProjectSpendPanel() {
  const [activeStatuses, setActiveStatuses] = useState<SpendStatus[]>([]);
  const [page, setPage] = useState(1);

  const filtered = useMemo(
    () =>
      activeStatuses.length === 0
        ? PROJECTS
        : PROJECTS.filter((project) => activeStatuses.includes(project.status)),
    [activeStatuses],
  );

  const pageCount = Math.max(1, Math.ceil(filtered.length / PAGE_SIZE));
  const currentPage = Math.min(page, pageCount);
  const visible = filtered.slice((currentPage - 1) * PAGE_SIZE, currentPage * PAGE_SIZE);

  const toggleStatus = (status: SpendStatus) => {
    setActiveStatuses((prev) =>
      prev.includes(status) ? prev.filter((item) => item !== status) : [...prev, status],
    );
    setPage(1);
  };

  const resetFilters = () => {
    setActiveStatuses([]);
    setPage(1);
  };

  const onChipKeyDown = (event: KeyboardEvent<HTMLSpanElement>, status: SpendStatus) => {
    if (event.key === 'Enter' || event.key === ' ') {
      event.preventDefault();
      toggleStatus(status);
    }
  };

  return (
    <section
      style={{
        display: 'flex',
        flexDirection: 'column',
        gap: '20px',
        padding: '20px',
        background: 'var(--jx-surface)',
        border: '1px solid var(--jx-border)',
        borderRadius: 'var(--jx-r-lg)',
        fontFamily: 'var(--jx-font-sans)',
        color: 'var(--jx-text)',
      }}
    >
      <header style={{ display: 'flex', flexDirection: 'column', gap: '12px' }}>
        <div
          style={{
            display: 'flex',
            flexWrap: 'wrap',
            alignItems: 'baseline',
            justifyContent: 'space-between',
            gap: '8px',
          }}
        >
          <h2
            style={{
              margin: 0,
              fontFamily: 'var(--jx-font-display)',
              fontSize: '20px',
              color: 'var(--jx-text)',
            }}
          >
            Расход по проектам
          </h2>
          <span style={{ fontSize: '13px', color: 'var(--jx-text-2)' }}>
            Показано {filtered.length} из {PROJECTS.length}
          </span>
        </div>

        <div
          role="group"
          aria-label="Фильтр по статусу"
          style={{ display: 'flex', flexWrap: 'wrap', gap: '8px' }}
        >
          {STATUS_ORDER.map((status) => {
            const isActive = activeStatuses.includes(status);
            return (
              <JxChip
                key={status}
                active={isActive}
                removable={isActive}
                onRemove={() => toggleStatus(status)}
                role="button"
                tabIndex={0}
                aria-pressed={isActive}
                onClick={() => toggleStatus(status)}
                onKeyDown={(event) => onChipKeyDown(event, status)}
              >
                {STATUS_META[status].label}
              </JxChip>
            );
          })}
        </div>
      </header>

      {visible.length === 0 ? (
        <JxEmptyState
          title="Под фильтры ничего не подошло"
          message="Ни один проект не имеет выбранных статусов. Снимите часть фильтров, чтобы снова увидеть список."
          action={
            <JxButton variant="primary" onClick={resetFilters}>
              Сбросить фильтры
            </JxButton>
          }
        />
      ) : (
        <>
          <ul
            style={{
              listStyle: 'none',
              margin: 0,
              padding: 0,
              display: 'flex',
              flexDirection: 'column',
            }}
          >
            {visible.map((project, index) => (
              <li key={project.id}>
                {index > 0 ? <JxDivider /> : null}
                <div
                  style={{
                    display: 'flex',
                    alignItems: 'center',
                    gap: '16px',
                    padding: '12px 0',
                  }}
                >
                  <JxProgressCircle
                    value={Math.min(project.quotaUsed, 100)}
                    showValue
                    aria-label={`Квота проекта «${project.name}» использована на ${project.quotaUsed}%`}
                  />
                  <div style={{ display: 'flex', flexDirection: 'column', gap: '4px', minWidth: 0, flex: 1 }}>
                    <span
                      style={{
                        fontSize: '15px',
                        color: 'var(--jx-text)',
                        overflow: 'hidden',
                        textOverflow: 'ellipsis',
                        whiteSpace: 'nowrap',
                      }}
                    >
                      {project.name}
                    </span>
                    <span style={{ fontSize: '13px', color: 'var(--jx-text-2)', fontFamily: 'var(--jx-font-mono)' }}>
                      {project.quotaUsed}% квоты
                    </span>
                  </div>
                  <JxBadge tone={STATUS_META[project.status].tone} dot>
                    {STATUS_META[project.status].label}
                  </JxBadge>
                </div>
              </li>
            ))}
          </ul>

          {pageCount > 1 ? (
            <div style={{ display: 'flex', justifyContent: 'center' }}>
              <JxPagination total={pageCount} page={currentPage} onPageChange={setPage} />
            </div>
          ) : null}
        </>
      )}
    </section>
  );
}

